css:
/* Nexum Invoice (PH) — wkhtmltopdf-safe (tables, no flex/grid). Brand slate palette. */
.nxi{font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;color:#1C2B30;font-size:10.5pt;line-height:1.4;position:relative}
.nxi table{border-collapse:collapse;width:100%;table-layout:fixed}
/* frappe print css forces `td,th{padding:6px/10px !important}` — zero it, then opt back in below */
.nxi td,.nxi th{vertical-align:top !important;padding:0 !important}
.nxi-draft{position:absolute;top:42%;left:0;right:0;text-align:center;font-size:72pt;font-weight:800;color:rgba(46,85,98,.08);letter-spacing:.2em;transform:rotate(-18deg);pointer-events:none}
.nxi-head{margin-bottom:18px;border-bottom:2px solid #2E5562;padding-bottom:14px}
.nxi .nxi-head > tbody > tr > td{padding:0 0 14px !important}
.nxi td.nxi-brand{width:61%}
.nxi td.nxi-brand > table{width:100%}
.nxi td.nxi-logo{width:72px;padding-right:14px !important}
.nxi td.nxi-logo img{width:56px !important;max-width:56px !important;height:auto;display:block}
.nxi-trade{font-size:13pt;font-weight:800;letter-spacing:0;color:#2E5562;text-transform:uppercase;line-height:1.2}
.nxi-reg{font-size:9.5pt;color:#1C2B30;margin-top:2px}
.nxi-addr,.nxi-contact{font-size:9pt;color:#5C7079;margin-top:2px}
.nxi-contact span{white-space:nowrap;display:inline-block}
.nxi-tin{font-size:9.5pt;font-weight:700;color:#1C2B30;margin-top:4px}
.nxi-meta{width:39%;text-align:right}
.nxi-title{font-size:26pt;font-weight:800;letter-spacing:.08em;color:#2E5562;line-height:1;margin-bottom:8px}
.nxi-paid{display:inline-block;font-size:9pt;font-weight:800;letter-spacing:.18em;color:#2E5562;border:2px solid #2E5562;border-radius:4px;padding:2px 10px;margin:0 0 8px}
.nxi-kv{width:100%}
.nxi .nxi-kv td{font-size:9.5pt;padding:1px 0 1px 10px !important;text-align:right}
.nxi .nxi-kv td:first-child{color:#5C7079;width:34%;white-space:nowrap}
.nxi .nxi-kv td:last-child{font-weight:600;color:#1C2B30;white-space:nowrap;overflow:visible}
.nxi-parties{margin-bottom:16px}
.nxi td.nxi-party{width:50%;padding:10px 12px !important;background:#F6F9FA;border:1px solid #DCE7EB}
.nxi td.nxi-party + td.nxi-party{border-left:0}
.nxi-label{font-size:8pt;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#5C7079;margin-bottom:3px}
.nxi-party-name{font-size:11.5pt;font-weight:700;color:#1C2B30}
.nxi-party-addr,.nxi-party-line{font-size:9.5pt;color:#1C2B30;margin-top:2px;white-space:pre-line}
.nxi-items{margin-bottom:14px}
.nxi .nxi-items th{background:#2E5562;color:#fff;font-size:8.5pt;font-weight:700;letter-spacing:.08em;text-transform:uppercase;padding:7px 8px !important;text-align:left}
.nxi .nxi-items td{padding:7px 8px !important;border-bottom:1px solid #DCE7EB;font-size:10pt}
.nxi-items .c-no{width:5%}.nxi-items td.c-no{color:#5C7079}
.nxi-items .c-qty,.nxi-items .c-rate,.nxi-items .c-amt{text-align:right;white-space:nowrap}
.nxi-items .c-qty{width:9%}.nxi-items .c-uom{width:9%}.nxi-items .c-rate{width:16%}.nxi-items .c-amt{width:18%}
.nxi-item-name{font-weight:600}
.nxi-item-desc{font-size:9pt;color:#5C7079;margin-top:2px}
.nxi-foot{margin-bottom:26px}
.nxi td.nxi-words{width:58%;padding-right:24px !important}
.nxi-words-text{font-size:10pt;font-style:italic;color:#1C2B30}
.nxi-legend{margin-top:10px;font-size:8.5pt;white-space:nowrap;font-weight:700;letter-spacing:.06em;color:#1C2B30;border:1px solid #1C2B30;display:inline-block;padding:4px 8px}
.nxi-terms{font-size:9pt;color:#5C7079;white-space:pre-line}
.nxi-totals{width:42%}
.nxi .nxi-sum td{padding:4px 8px !important;font-size:10pt;border-bottom:1px solid #EAF1F3}
.nxi .nxi-sum td:last-child{text-align:right;white-space:nowrap;font-weight:600}
.nxi .nxi-sum td:first-child{color:#5C7079}
.nxi .nxi-sum .nxi-grand td{background:#EAF1F3;font-size:12pt;font-weight:800;color:#2E5562;border-bottom:2px solid #2E5562;padding:7px 8px !important}
.nxi .nxi-sum .nxi-due td{font-weight:800;color:#1C2B30}
/* a tax already inside the prices ("incl. VAT 12%"): informational, not part of the sum */
.nxi .nxi-sum .nxi-incl td{font-size:9pt;font-weight:400;color:#5C7079}
.nxi-sign{margin:10px 0 18px}
.nxi .nxi-sign td{width:50%;padding:0 40px 0 0 !important}
.nxi-sig-line{border-bottom:1px solid #1C2B30;height:34px;width:78%}
.nxi-sig-cap{font-size:8.5pt;color:#5C7079;margin-top:4px;letter-spacing:.06em;text-transform:uppercase}
.nxi-permit{font-size:8.5pt;color:#5C7079;border-top:1px solid #DCE7EB;padding-top:8px;margin-top:6px}
.nxi-thanks{font-size:9pt;color:#2E5562;font-weight:600;margin-top:10px;text-align:center;letter-spacing:.04em}

html:
{#- Nexum Invoice (PH) — self-contained Jinja print format (no Letter Head).
    Reads Company (+ its default Address) for the header and the BIR qualifiers. -#}
{%- set company = frappe.get_doc("Company", doc.company) -%}
{#- Seller address: the one picked on the invoice (Company Address), else the company's
    primary enabled address, else its oldest enabled one. The old single unordered Dynamic
    Link lookup printed whichever linked address sorted first, even a disabled one
    (batch205 idx 95). Invoices made by the API or Auto Repeat can carry no
    company_address, hence the fallback. -#}
{%- set addr_name = doc.get("company_address") -%}
{%- if not addr_name -%}
  {%- set linked = frappe.get_all("Dynamic Link", filters={"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, pluck="parent") -%}
  {%- set ranked = frappe.get_all("Address", filters={"name": ["in", linked], "disabled": 0}, order_by="is_primary_address desc, creation asc", pluck="name", limit=1) if linked else [] -%}
  {%- set addr_name = ranked[0] if ranked else None -%}
{%- endif -%}
{%- set caddr = frappe.get_doc("Address", addr_name) if addr_name and frappe.db.exists("Address", addr_name) else None -%}
{%- set taxreg = (company.get("nx_tax_registration") or "").strip() -%}
{%- set tin_label = ("NON-VAT Reg. TIN" if taxreg == "Non-VAT" else ("VAT Reg. TIN" if taxreg == "VAT" else "TIN")) -%}
{%- set is_return = doc.get("is_return") -%}
{%- set title = ("CREDIT NOTE" if is_return else ("DEBIT NOTE" if doc.get("is_debit_note") else "INVOICE")) -%}
{%- set cur = doc.currency -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v, currency=cur) }}{%- endmacro -%}
{%- set logo = company.company_logo -%}
{%- set trade = company.company_name -%}
{%- set regname = (company.get("nx_registered_name") or "").strip() -%}
<div class="nxi">
  {%- if doc.docstatus == 0 %}<div class="nxi-draft">DRAFT</div>{% endif -%}
  {%- if doc.docstatus == 2 %}<div class="nxi-draft">CANCELLED</div>{% endif -%}

  <table class="nxi-head"><tr>
    <td class="nxi-brand">
      <table><tr>
        {%- if logo %}<td class="nxi-logo"><img src="{{ logo }}" alt=""></td>{% endif -%}
        <td>
          <div class="nxi-trade">{{ trade }}</div>
          {%- if regname and regname.upper() != trade.upper() %}<div class="nxi-reg">{{ regname }}</div>{% endif -%}
          {%- if caddr %}
          <div class="nxi-addr">{{ caddr.address_line1 }}{% if caddr.address_line2 %}, {{ caddr.address_line2 }}{% endif %}{% if caddr.city %}, {{ caddr.city }}{% endif %}{% if caddr.state %}, {{ caddr.state }}{% endif %}{% if caddr.pincode %} {{ caddr.pincode }}{% endif %}</div>
          {%- endif %}
          {%- if company.tax_id %}<div class="nxi-tin">{{ tin_label }} {{ company.tax_id }}</div>{% endif -%}
          <div class="nxi-contact">
            {%- if company.phone_no %}<span>{{ company.phone_no }}</span>{% endif -%}
            {%- if company.phone_no and company.email %}&nbsp;&nbsp;·&nbsp;&nbsp;{% endif -%}
            {%- if company.email %}<span>{{ company.email }}</span>{% endif -%}
            {%- if company.website %}<br>{{ company.website }}{% endif -%}
          </div>
        </td>
      </tr></table>
    </td>
    <td class="nxi-meta">
      <div class="nxi-title">{{ title }}</div>
      {%- if doc.docstatus == 1 and not is_return and doc.get("outstanding_amount") is not none and doc.outstanding_amount <= 0 and (doc.grand_total or 0) > 0 %}<div class="nxi-paid">PAID</div>{% endif -%}
      <table class="nxi-kv">
        <tr><td>Invoice No.</td><td>{{ doc.name }}</td></tr>
        <tr><td>Date</td><td>{{ frappe.utils.formatdate(doc.posting_date, "dd MMM yyyy") }}</td></tr>
        {%- if doc.due_date and not is_return %}<tr><td>Due Date</td><td>{{ frappe.utils.formatdate(doc.due_date, "dd MMM yyyy") }}</td></tr>{% endif -%}
        {%- if doc.get("po_no") %}<tr><td>Your Ref / PO</td><td>{{ doc.po_no }}</td></tr>{% endif -%}
        {%- if doc.get("return_against") %}<tr><td>Against</td><td>{{ doc.return_against }}</td></tr>{% endif -%}
        {%- if doc.get("payment_terms_template") %}<tr><td>Terms</td><td>{{ doc.payment_terms_template }}</td></tr>{% endif -%}
      </table>
    </td>
  </tr></table>

  <table class="nxi-parties"><tr>
    <td class="nxi-party">
      <div class="nxi-label">Billed to</div>
      <div class="nxi-party-name">{{ doc.customer_name }}</div>
      {%- if doc.get("address_display") %}<div class="nxi-party-addr">{{ doc.address_display }}</div>{% endif -%}
      {%- if doc.get("tax_id") %}<div class="nxi-party-line">TIN {{ doc.tax_id }}</div>{% endif -%}
      {%- if doc.get("contact_display") and (doc.contact_display or "").strip().lower() != (doc.customer_name or "").strip().lower() %}<div class="nxi-party-line">Attn: {{ doc.contact_display }}</div>{% endif -%}
    </td>
    {%- if doc.get("shipping_address") and doc.shipping_address != doc.get("address_display") %}
    <td class="nxi-party">
      <div class="nxi-label">Ship to</div>
      <div class="nxi-party-addr">{{ doc.shipping_address }}</div>
    </td>
    {%- endif %}
    {%- if doc.get("project") or doc.get("cost_center") %}
    <td class="nxi-party nxi-party-right">
      {%- if doc.get("project") %}<div class="nxi-label">Project</div><div class="nxi-party-line">{{ doc.project }}</div>{% endif -%}
    </td>
    {%- endif %}
  </tr></table>

  <table class="nxi-items">
    <thead><tr>
      <th class="c-no">#</th>
      <th class="c-desc">Description</th>
      <th class="c-qty">Qty</th>
      <th class="c-uom">Unit</th>
      <th class="c-rate">Unit Price</th>
      <th class="c-amt">Amount</th>
    </tr></thead>
    <tbody>
    {%- for row in doc.items %}
      <tr>
        <td class="c-no">{{ loop.index }}</td>
        <td class="c-desc">
          <div class="nxi-item-name">{{ row.item_name }}</div>
          {%- if row.description and row.description != row.item_name %}<div class="nxi-item-desc">{{ row.description }}</div>{% endif -%}
        </td>
        <td class="c-qty">{{ row.get_formatted("qty") }}</td>
        <td class="c-uom">{{ row.uom or row.stock_uom or "" }}</td>
        <td class="c-rate">{{ money(row.rate) }}</td>
        <td class="c-amt">{{ money(row.amount) }}</td>
      </tr>
    {%- endfor %}
    </tbody>
  </table>

  <table class="nxi-foot"><tr>
    <td class="nxi-words">
      <div class="nxi-label">Amount in words</div>
      <div class="nxi-words-text">{{ doc.in_words }}</div>
      {%- if taxreg == "Non-VAT" %}<div class="nxi-legend">THIS DOCUMENT IS NOT VALID FOR CLAIM OF INPUT TAX</div>{% endif -%}
      {%- if doc.get("terms") %}<div class="nxi-label" style="margin-top:10px">Notes</div><div class="nxi-terms">{{ doc.terms }}</div>{% endif -%}
    </td>
    <td class="nxi-totals">
      {#- The lines must add up to Total whatever the tax setup (batch205 idx 91). A tax
          "included in the basic rate" is already inside the item amounts, hence inside
          Subtotal: it is shown under Total as "incl. ..." (the VAT stays its own line, as
          BIR wants), never added a second time. With such a tax the added taxes are shown
          after discount and the discount on the same VAT-inclusive footing (Subtotal +
          added taxes - Total): the stored discount when it is on the Grand Total, its
          VAT-inclusive equivalent when it is on the Net Total. Invoices without an
          included tax print exactly as before. -#}
      {%- set incl = doc.taxes | selectattr("included_in_print_rate") | list -%}
      {%- set added = doc.taxes | rejectattr("included_in_print_rate") | list -%}
      {%- set tax_field = "tax_amount_after_discount_amount" if incl else "tax_amount" -%}
      {%- set discount = doc.get("discount_amount") or 0 -%}
      {%- if discount and incl -%}
        {%- set ns = namespace(added=0) -%}
        {%- for t in added %}{% set ns.added = ns.added + (t.get(tax_field) or 0) %}{% endfor -%}
        {%- set discount = (doc.total or 0) + ns.added - (doc.grand_total or 0) -%}
      {%- endif -%}
      <table class="nxi-sum">
        <tr><td>Subtotal</td><td>{{ money(doc.total) }}</td></tr>
        {%- if discount %}<tr><td>Discount{% if doc.get("additional_discount_percentage") %} ({{ doc.additional_discount_percentage }}%){% endif %}</td><td>- {{ money(discount) }}</td></tr>{% endif -%}
        {%- for t in added %}{% if t.get(tax_field) %}
        <tr><td>{{ t.description }}</td><td>{{ money(t.get(tax_field)) }}</td></tr>
        {%- endif %}{% endfor %}
        {%- if doc.get("rounding_adjustment") and not doc.get("disable_rounded_total") %}<tr><td>Rounding</td><td>{{ money(doc.rounding_adjustment) }}</td></tr>{% endif -%}
        <tr class="nxi-grand"><td>Total {% if cur != company.default_currency %}({{ cur }}){% endif %}</td><td>{{ money(doc.rounded_total if (doc.get("rounded_total") and not doc.get("disable_rounded_total")) else doc.grand_total) }}</td></tr>
        {%- for t in incl %}{% if t.tax_amount_after_discount_amount %}
        <tr class="nxi-incl"><td>incl. {{ t.description }}</td><td>{{ money(t.tax_amount_after_discount_amount) }}</td></tr>
        {%- endif %}{% endfor %}
        {#- outstanding_amount is kept in the party account's currency: ERPNext works it out
            from the base (company-currency) totals when that differs from the invoice
            currency, e.g. a USD invoice on the company's PHP Debtors account. So compare it
            with the total in that currency and print Paid / Amount Due in it (batch205 idx
            89); in the invoice currency an unpaid USD 100 invoice at 56 printed
            "Paid $-5,500.00 / Amount Due $5,600.00". Once nothing is owed, the invoice
            currency is exact again (Paid = Total), so a settled invoice keeps it. -#}
        {%- set pac = doc.get("party_account_currency") or cur -%}
        {%- if doc.get("outstanding_amount") == 0 -%}{%- set pac = cur -%}{%- endif -%}
        {%- set due_total = (doc.rounded_total or doc.grand_total) if pac == cur else (doc.base_rounded_total or doc.base_grand_total) -%}
        {%- if doc.docstatus == 1 and doc.get("outstanding_amount") is not none and doc.outstanding_amount != due_total and not is_return %}
        <tr><td>Paid{% if pac != cur %} ({{ pac }}){% endif %}</td><td>{{ frappe.utils.fmt_money(due_total - doc.outstanding_amount, currency=pac) }}</td></tr>
        <tr class="nxi-due"><td>Amount Due{% if pac != cur %} ({{ pac }}){% endif %}</td><td>{{ frappe.utils.fmt_money(doc.outstanding_amount, currency=pac) }}</td></tr>
        {%- endif %}
      </table>
    </td>
  </tr></table>

  <table class="nxi-sign"><tr>
    <td><div class="nxi-sig-line"></div><div class="nxi-sig-cap">Prepared by</div></td>
    <td><div class="nxi-sig-line"></div><div class="nxi-sig-cap">Received by / Date</div></td>
  </tr></table>

  {%- if company.get("nx_invoice_footer") %}<div class="nxi-permit">{{ company.nx_invoice_footer | replace("\n", "<br>") }}</div>{% endif -%}
  <div class="nxi-thanks">Thank you for your business.</div>
</div>
